function J = dp_jacobian(th1, om1, th2, om2, m1, m2, L1, L2, g)
%% DP_JACOBIAN  Analytic Jacobian of the double-pendulum vector field.
%%
%%   State y = [th1; om1; th2; om2],  rhs = [om1; a1; om2; a2].
%%   Returns J = d(rhs)/dy as a 4x4 matrix.
%%
%%   GENERATED by dp_v2/gen/gen_jacobian.py -- do not edit by hand.
%%
%%   An ANALYTIC Jacobian is used deliberately.  Differencing the vector
%%   field numerically would inject an O(h) error straight into the tangent
%%   flow, biasing the Lyapunov exponent -- the very quantity we measure.

    % The common-subexpression block below is machine-generated; all
    % intermediates are scalars, so the element-wise operators that
    % octave_code emits are equivalent to plain scalar operations.

    % --- common subexpressions ---
    t0 = th1 - th2;
    t1 = cos(t0);
    t2 = t1.^2;
    t3 = m1 + m2;
    t4 = -m2.*t2 + t3;
    t5 = -t4;
    t6 = g.*t3;
    t7 = t6.*cos(th1);
    t8 = m2.*t2;
    t9 = om1.^2;
    t10 = L1.*t9;
    t11 = L2.*om2.^2;
    t12 = t1.*t11;
    t13 = sin(th2);
    t14 = sin(t0);
    t15 = g.*t13.*t14;
    t16 = t14.^2;
    t17 = t6.*sin(th1);
    t18 = m2.*t11;
    t19 = 2*th1 - 2*th2;
    t20 = sin(t19);
    t21 = m2.*t20;
    t22 = g.*t1;
    t23 = 2*t14;
    t24 = t1.*t23;
    t25 = t24.*(-m2.*t13.*t22 + t10.*t21/2 + t14.*t18 + t17);
    t26 = 1./L1;
    t27 = t5.^(-2);
    t28 = t26.*t27;
    t29 = 2*t21./(2*m1 - m2.*cos(t19) + m2);
    t30 = cos(th2);
    t31 = t10.*t3;
    t32 = t1.*t31 + t11.*t8 - t14.*t17 - t16.*t18;
    t33 = m2.*t24.*(t1.*t17 - t13.*t6 + t14.*t31 + t18.*t20/2);
    t34 = 1./L2;
    t35 = t27.*t34;

    % --- Jacobian entries ---
    J21 = t28.*(m2.*t25 + t5.*(-m2.*t10.*t16 + m2.*t12 + m2.*t15 + t10.*t8 + t7));
    J22 = -om1.*t29;
    J23 = m2.*t28.*(-t25 + t5.*(L1.*t16.*t9 - t10.*t2 - t12 - t15 - t22.*t30));
    J24 = L2.*m2.*om2.*t23.*t26./t5;
    J41 = t35.*(-t33 - t5.*(t1.*t7 + t32));
    J42 = L1.*om1.*t23.*t3.*t34./t4;
    J43 = t35.*(t33 + t5.*(t30.*t6 + t32));
    J44 = om2.*t29;

    J = [ 0,   1,   0,   0;
         J21, J22, J23, J24;
          0,   0,   0,   1;
         J41, J42, J43, J44];
end
